import 'package:flutter/material.dart';
import 'package:share_plus/share_plus.dart';

class TextShareExample extends StatelessWidget {
  const TextShareExample({super.key});

  // 텍스트 공유
  void _shareText() {
    Share.share('안녕하세요! Flutter로 만든 앱입니다.');
  }

  // 제목과 함께 공유
  void _shareWithSubject() {
    Share.share(
      '이 앱을 확인해보세요!\n\nhttps://flutter.dev',
      subject: '멋진 앱 추천',
    );
  }

  // URL 공유
  void _shareUrl() {
    Share.shareUri(Uri.parse('https://flutter.dev'));
  }

  // 공유 결과 확인
  Future<void> _shareWithResult(BuildContext context) async {
    final result = await Share.shareWithResult(
      '공유할 텍스트입니다.',
      subject: '공유 테스트',
    );

    // 결과 확인
    String message;
    switch (result.status) {
      case ShareResultStatus.success:
        message = '공유 성공!';
        break;
      case ShareResultStatus.dismissed:
        message = '공유 취소됨';
        break;
      case ShareResultStatus.unavailable:
        message = '공유 불가';
        break;
    }

    if (context.mounted) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(message)),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('텍스트 공유')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            ElevatedButton.icon(
              onPressed: _shareText,
              icon: const Icon(Icons.share),
              label: const Text('텍스트 공유'),
            ),
            const SizedBox(height: 16),
            ElevatedButton.icon(
              onPressed: _shareWithSubject,
              icon: const Icon(Icons.email),
              label: const Text('제목과 함께 공유'),
            ),
            const SizedBox(height: 16),
            ElevatedButton.icon(
              onPressed: _shareUrl,
              icon: const Icon(Icons.link),
              label: const Text('URL 공유'),
            ),
            const SizedBox(height: 16),
            ElevatedButton.icon(
              onPressed: () => _shareWithResult(context),
              icon: const Icon(Icons.check),
              label: const Text('결과 확인하며 공유'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'dart:io';
import 'package:flutter/material.dart';
import 'package:share_plus/share_plus.dart';
import 'package:path_provider/path_provider.dart';

class FileShareExample extends StatelessWidget {
  const FileShareExample({super.key});

  // 단일 파일 공유
  Future<void> _shareFile() async {
    // 임시 파일 생성 (실제로는 갤러리나 다운로드된 파일 사용)
    final directory = await getTemporaryDirectory();
    final file = File('${directory.path}/test.txt');
    await file.writeAsString('공유할 파일 내용입니다.');

    await Share.shareXFiles(
      [XFile(file.path)],
      text: '파일을 공유합니다.',
      subject: '파일 공유',
    );
  }

  // 이미지 공유 (에셋에서)
  Future<void> _shareImageFromAsset(BuildContext context) async {
    // 에셋을 임시 파일로 복사
    final ByteData bytes = await DefaultAssetBundle.of(context)
        .load('assets/images/sample.png');
    final directory = await getTemporaryDirectory();
    final file = File('${directory.path}/share_image.png');
    await file.writeAsBytes(bytes.buffer.asUint8List());

    await Share.shareXFiles(
      [XFile(file.path)],
      text: '멋진 이미지를 공유합니다!',
    );
  }

  // 여러 파일 공유
  Future<void> _shareMultipleFiles() async {
    final directory = await getTemporaryDirectory();

    // 여러 파일 생성
    final file1 = File('${directory.path}/doc1.txt');
    await file1.writeAsString('첫 번째 문서');

    final file2 = File('${directory.path}/doc2.txt');
    await file2.writeAsString('두 번째 문서');

    await Share.shareXFiles(
      [
        XFile(file1.path),
        XFile(file2.path),
      ],
      text: '여러 파일을 공유합니다.',
    );
  }

  // MIME 타입 지정
  Future<void> _shareWithMimeType() async {
    final directory = await getTemporaryDirectory();
    final file = File('${directory.path}/data.json');
    await file.writeAsString('{"name": "test"}');

    await Share.shareXFiles(
      [XFile(file.path, mimeType: 'application/json')],
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('파일 공유')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            ElevatedButton.icon(
              onPressed: _shareFile,
              icon: const Icon(Icons.insert_drive_file),
              label: const Text('파일 공유'),
            ),
            const SizedBox(height: 16),
            ElevatedButton.icon(
              onPressed: () => _shareImageFromAsset(context),
              icon: const Icon(Icons.image),
              label: const Text('이미지 공유'),
            ),
            const SizedBox(height: 16),
            ElevatedButton.icon(
              onPressed: _shareMultipleFiles,
              icon: const Icon(Icons.folder),
              label: const Text('여러 파일 공유'),
            ),
            const SizedBox(height: 16),
            ElevatedButton.icon(
              onPressed: _shareWithMimeType,
              icon: const Icon(Icons.code),
              label: const Text('MIME 타입 지정'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:share_plus/share_plus.dart';

class iPadShareExample extends StatelessWidget {
  const iPadShareExample({super.key});

  // 버튼 위치에 공유 시트 표시
  void _shareAtButtonPosition(BuildContext context, Rect sharePositionOrigin) {
    Share.share(
      '공유할 텍스트입니다.',
      sharePositionOrigin: sharePositionOrigin,
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('iPad 공유')),
      body: Center(
        child: Builder(
          builder: (context) {
            return ElevatedButton.icon(
              onPressed: () {
                // 버튼의 위치와 크기 가져오기
                final box = context.findRenderObject() as RenderBox;
                final position = box.localToGlobal(Offset.zero);
                final size = box.size;

                final rect = Rect.fromLTWH(
                  position.dx,
                  position.dy,
                  size.width,
                  size.height,
                );

                _shareAtButtonPosition(context, rect);
              },
              icon: const Icon(Icons.share),
              label: const Text('여기서 공유'),
            );
          },
        ),
      ),
    );
  }
}

// 공유 버튼 위젯
class ShareButton extends StatelessWidget {
  final String text;
  final String? subject;
  final List<XFile>? files;

  const ShareButton({
    super.key,
    required this.text,
    this.subject,
    this.files,
  });

  @override
  Widget build(BuildContext context) {
    return Builder(
      builder: (context) {
        return IconButton(
          icon: const Icon(Icons.share),
          onPressed: () async {
            final box = context.findRenderObject() as RenderBox;
            final position = box.localToGlobal(Offset.zero);
            final rect = Rect.fromLTWH(
              position.dx,
              position.dy,
              box.size.width,
              box.size.height,
            );

            if (files != null && files!.isNotEmpty) {
              await Share.shareXFiles(
                files!,
                text: text,
                subject: subject,
                sharePositionOrigin: rect,
              );
            } else {
              await Share.share(
                text,
                subject: subject,
                sharePositionOrigin: rect,
              );
            }
          },
        );
      },
    );
  }
}

import 'dart:typed_data';
