// 상품 공유
class ProductShareExample extends StatelessWidget {
  final String productName;
  final String productUrl;
  final int price;

  const ProductShareExample({
    super.key,
    required this.productName,
    required this.productUrl,
    required this.price,
  });

  void _shareProduct(BuildContext context) {
    final text = '''
$productName

가격: ${price.toString().replaceAllMapped(
      RegExp(r'(\d)(?=(\d{3})+(?!\d))'),
      (m) => '${m[1]},',
    )}원

지금 확인하기: $productUrl''';

    final box = context.findRenderObject() as RenderBox?;
    final rect = box != null
        ? Rect.fromLTWH(
            box.localToGlobal(Offset.zero).dx,
            box.localToGlobal(Offset.zero).dy,
            box.size.width,
            box.size.height,
          )
        : null;

    Share.share(
      text,
      subject: '$productName 추천',
      sharePositionOrigin: rect,
    );
  }

  @override
  Widget build(BuildContext context) {
    return Card(
      child: Padding(
        padding: const EdgeInsets.all(16),
        child: Column(
          crossAxisAlignment: CrossAxisAlignment.start,
          children: [
            Text(productName, style: const TextStyle(fontSize: 18, fontWeight: FontWeight.bold)),
            const SizedBox(height: 8),
            Text('${price}원'),
            const SizedBox(height: 16),
            Row(
              children: [
                Expanded(
                  child: ElevatedButton(
                    onPressed: () {},
                    child: const Text('구매하기'),
                  ),
                ),
                const SizedBox(width: 8),
                Builder(
                  builder: (context) => IconButton(
                    icon: const Icon(Icons.share),
                    onPressed: () => _shareProduct(context),
                  ),
                ),
              ],
            ),
          ],
        ),
      ),
    );
  }
}

// 스크린샷 공유
class ScreenshotShareWidget extends StatefulWidget {
  final Widget child;

  const ScreenshotShareWidget({super.key, required this.child});

  @override
  State<ScreenshotShareWidget> createState() => _ScreenshotShareWidgetState();
}

class _ScreenshotShareWidgetState extends State<ScreenshotShareWidget> {
  final GlobalKey _screenshotKey = GlobalKey();

  Future<void> _captureAndShare() async {
    try {
      // 위젯을 이미지로 캡처
      final boundary = _screenshotKey.currentContext!.findRenderObject()
          as RenderRepaintBoundary;
      final image = await boundary.toImage(pixelRatio: 3.0);
      final byteData = await image.toByteData(format: ui.ImageByteFormat.png);
      final bytes = byteData!.buffer.asUint8List();

      // 임시 파일로 저장
      final directory = await getTemporaryDirectory();
      final file = File('${directory.path}/screenshot.png');
      await file.writeAsBytes(bytes);

      // 공유
      await Share.shareXFiles(
        [XFile(file.path)],
        text: '앱에서 캡처한 이미지입니다.',
      );
    } catch (e) {
      debugPrint('스크린샷 공유 실패: $e');
    }
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        RepaintBoundary(
          key: _screenshotKey,
          child: widget.child,
        ),
        const SizedBox(height: 16),
        ElevatedButton.icon(
          onPressed: _captureAndShare,
          icon: const Icon(Icons.screenshot),
          label: const Text('스크린샷 공유'),
        ),
      ],
    );
  }
}

